"""Requirement-driven tests for slugify.py and its command-line wrapper."""

from pathlib import Path
import re
import subprocess
import sys
import unittest

from slugify import slugify


CLI_PATH = Path(__file__).resolve().with_name("slug_cli.py")


class SlugifyTests(unittest.TestCase):
    def test_unicode_decomposition(self):
        self.assertEqual(slugify("Café déjà vu"), "cafe-deja-vu")
        self.assertEqual(slugify("Cafe\u0301"), "cafe")

    def test_nfkd_compatibility_characters(self):
        self.assertEqual(slugify("ＡＢＣ １２３ ﬁle"), "abc-123-file")

    def test_non_ascii_characters_are_discarded(self):
        self.assertEqual(slugify("snow 雪 café"), "snow-cafe")
        self.assertEqual(slugify("Straße"), "strae")

    def test_punctuation_runs_and_edge_separators(self):
        self.assertEqual(slugify("  Hello___WORLD!!! & 42... "), "hello-world-42")
        self.assertEqual(slugify("a\t\n\rb / c"), "a-b-c")

    def test_ascii_letters_and_digits_are_preserved(self):
        self.assertEqual(slugify("AZaz09"), "azaz09")

    def test_empty_and_punctuation_fallback(self):
        for text in ("", "   ", "___ -- !!!", "雪☃😀"):
            with self.subTest(text=text):
                self.assertEqual(slugify(text), "untitled")

    def test_fallback_is_truncated(self):
        self.assertEqual(slugify("", 3), "unt")
        self.assertEqual(slugify("!!!", 1), "u")

    def test_default_limit_is_48(self):
        self.assertEqual(slugify("A" * 70), "a" * 48)

    def test_truncation_occurs_after_normalization(self):
        self.assertEqual(slugify("Éléphant", max_length=4), "elep")

    def test_truncation_strips_trailing_hyphen(self):
        self.assertEqual(slugify("alpha beta", 6), "alpha")
        self.assertEqual(slugify("alpha beta", 7), "alpha-b")

    def test_minimum_length(self):
        self.assertEqual(slugify("ABC", 1), "a")

    def test_maximum_length(self):
        self.assertEqual(slugify("X" * 150, 128), "x" * 128)

    def test_text_must_be_a_string(self):
        for value in (None, 0, 1.5, True, b"abc", [], {}, object()):
            with self.subTest(value=repr(value)):
                with self.assertRaises(TypeError):
                    slugify(value)

    def test_invalid_length_values(self):
        for value in (0, -1, 129, 1000, 1.0, 2.5, "3", None, [], {}):
            with self.subTest(value=repr(value)):
                with self.assertRaises(ValueError):
                    slugify("hello", value)

    def test_boolean_length_is_invalid(self):
        for value in (False, True):
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    slugify("hello", value)

    def test_output_invariants_across_lengths(self):
        for text in ("", "☃", "A B C D", "___x___", "Café_" * 40):
            for limit in (1, 2, 7, 48, 128):
                with self.subTest(text=text, limit=limit):
                    result = slugify(text, limit)
                    self.assertIsInstance(result, str)
                    self.assertGreater(len(result), 0)
                    self.assertLessEqual(len(result), limit)
                    self.assertIsNotNone(re.fullmatch(r"[a-z0-9]+(?:-[a-z0-9]+)*", result))


class SlugCliTests(unittest.TestCase):
    def run_cli(self, *arguments):
        return subprocess.run(
            [sys.executable, str(CLI_PATH), *arguments],
            capture_output=True,
            text=True,
            encoding="utf-8",
            timeout=10,
            check=False,
        )

    def assert_cli_error(self, *arguments):
        result = self.run_cli(*arguments)
        self.assertNotEqual(result.returncode, 0)
        self.assertNotIn("Traceback", result.stdout + result.stderr)
        return result

    def test_default_cli_success(self):
        result = self.run_cli("Hello, World!")
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(result.stdout, "hello-world\n")

    def test_cli_custom_limit(self):
        result = self.run_cli("alpha beta", "--max-length", "6")
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(result.stdout, "alpha\n")

    def test_cli_unicode(self):
        result = self.run_cli("Café déjà vu")
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(result.stdout, "cafe-deja-vu\n")

    def test_cli_empty_argument_fallback(self):
        result = self.run_cli("", "--max-length", "3")
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(result.stdout, "unt\n")

    def test_cli_default_limit(self):
        result = self.run_cli("A" * 70)
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(result.stdout, "a" * 48 + "\n")

    def test_cli_valid_boundary_lengths(self):
        for limit in (1, 128):
            with self.subTest(limit=limit):
                result = self.run_cli("X" * 150, "--max-length", str(limit))
                self.assertEqual(result.returncode, 0, result.stderr)
                self.assertEqual(result.stdout, "x" * limit + "\n")

    def test_cli_invalid_lengths_have_no_traceback(self):
        for value in ("0", "-1", "129", "abc", "1.5", "True"):
            with self.subTest(value=value):
                self.assert_cli_error("hello", "--max-length", value)

    def test_cli_missing_text_has_no_traceback(self):
        self.assert_cli_error()

    def test_cli_extra_positional_argument_is_rejected(self):
        self.assert_cli_error("first", "second")

    def test_cli_help_works_without_text(self):
        result = self.run_cli("--help")
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertIn("--max-length", result.stdout)
        self.assertIn("usage", result.stdout.lower())
        self.assertNotIn("Traceback", result.stdout + result.stderr)


if __name__ == "__main__":
    unittest.main()

